mapper.select:
SELECT DISTINCT student.id FROM student LEFT JOIN batch_student_eligibility eligibility ON eligibility.student_id=student.id LEFT JOIN room_assignment residency ON residency.student_id=student.id AND residency.assignment_status='ACTIVE' LEFT JOIN room ON room.id=residency.room_id LEFT JOIN dormitory_floor floor ON floor.id=room.floor_id LEFT JOIN dormitory_building building ON building.id=floor.building_id WHERE student.student_status='ACTIVE'
AND eligibility.batch_id IN #{id}
AND student.major_id IN #{id}
AND student.grade_year IN #{value}
AND student.degree_level IN #{value}
AND student.student_category IN #{value}
AND building.id IN #{id}
AND NOT EXISTS ( SELECT 1 FROM bed_assignment assignment WHERE assignment.student_id=student.id AND assignment.assignment_status='ACTIVE'
AND assignment.batch_id IN #{id}
)
AND student.selection_review_status='PENDING'
ORDER BY student.id
